import sys

def find_min_operations(matrix, N):
    def is_sorted(matrix):
        return all(matrix[i][j] == (i * N + j + 1) for i in range(N) for j in range(N))

    def transpose(matrix, L):
        for i in range(L):
            for j in range(i + 1, L):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    operations = 0
    for L in range(N, 0, -1):
        if not is_sorted(matrix[:L][:L]):
            transpose(matrix, L)
            operations += 1
    return operations

input = sys.stdin.read().strip().split()
index = 0
results = []
while index < len(input):
    T = int(input[index])
    index += 1
    for _ in range(T):
        N = int(input[index])
        index += 1
        matrix = []
        for _ in range(N):
            row = list(map(int, input[index:index + N]))
            matrix.append(row)
            index += N
        results.append(find_min_operations(matrix, N))
print("\n".join(map(str, results)))
